import { GIFT_CATALOG } from '../../../../supabase/functions/_shared/pure/giftCatalog.ts';

// The pack accessories' drawings (docs/SPEC_V4.md §4.U), in the canvas's 100-unit box. The first
// catalog's seven (retired, Aura v134 KapsulAksesuar) were drawn on a capsule with its visor lower
// and are set on the app's capsule by an anchor: a hat by the head's top, glasses by the visor, the
// headphones half way. The 40 + 20 of "Genişleyen katalog" (AksesuarSiradan, AksesuarNadir,
// AksesuarDestansi, AksesuarEfsanevi, PaketElf, PaketNinja) are drawn on the app's own capsule
// (the body 52 wide with its top at 22, the visor's middle at 45.2; in capsuleDrawing.js 28 wide,
// its top at 8, the visor's middle at 20.5): one scale sets them (`body`).
// `back` lies behind the body (an Efsanevi's halo), `skin` over the body and under the visor (a
// Renk accessory), `art` over everything. A group that moves (capsuleFx.ts) is a
// `<g data-fx="…" data-o="x y" data-k="…">`: its motion, its origin and its unit in the canvas's
// units.
export type AccessoryAnchor = 'head' | 'face' | 'mid' | 'body';
export type AccessoryArt = {
  anchor: AccessoryAnchor;
  art: string;
  back?: string;
  skin?: string;
};

