// The canvas drew these without the capsule's own mouth (the accessory is the mouth).
const NO_MOUTH = new Set([
  'kedibiyiklari',
  'dalgictakimi',
  'seftakimi',
  'ejdernefesi',
  'sihirliflut',
  'dumanpecesi',
  'klanisareti',
]);

// The canvas's capsule in the app's units: as wide (52 → 28), from the same left edge (24 → 10).
const SCALE = 28 / 52;
const LEFT = 10 - 24 * SCALE;
const TOP: Record<AccessoryAnchor, number> = {
  head: 8 - 22 * SCALE,
  body: 8 - 22 * SCALE,
  face: 20.5 - 52 * SCALE,
  mid: 14.25 - 37 * SCALE,
};

function slotsOf(id: string): readonly string[] {
  return GIFT_CATALOG.accessories.find((a) => a.id === id)?.slots ?? [];
}

// Drawn in this order of their first slot: a skin first, then the eyes, the mouth, the neck, the
// face, the head (a hat over the glasses).
const DRAW_ORDER = ['c', 'e', 'm', 'n', 'f', 'h'];

function rank(id: string): number {
  const at = slotsOf(id)
    .map((s) => DRAW_ORDER.indexOf(s))
    .filter((i) => i >= 0);
  return at.length > 0 ? Math.min(...at) : DRAW_ORDER.length;
}

const num = (v: number) => String(Math.round(v * 1000) / 1000);

// A part set on the app's capsule: in a group that scales and moves it, its motions' origins and
// units in the capsule's own units.
function placed(part: string, dx: number, dy: number, s: number): string {
  const moved = part.replace(
    /data-o="(-?[\d.]+) (-?[\d.]+)" data-k="([\d.]+)"/g,
    (_m, x: string, y: string, k: string) =>
      `data-o="${num(Number(x) * s + dx)} ${num(Number(y) * s + dy)}" data-k="${num(Number(k) * s)}"`,
  );
  return `<g transform="translate(${dx.toFixed(3)} ${dy.toFixed(3)}) scale(${s.toFixed(5)})">${moved}</g>`;
}

export type AccessoryLayers = { back: string; skin: string; front: string; edge: string };

// The worn accessories' layers for the app's capsule drawing (its 48-unit box); an unknown id (an
// accessory a newer catalog has) is left out: the old app draws the capsule without it.
// `edge` (canvas units, 0 for none): a thin white contour under the art (the card, where the
// accessory reaches over its ring onto the card's ground).
export function accessoryLayers(ids: readonly string[], edge = 0): AccessoryLayers {
  const known = ids.filter((id) => ACCESSORY_ART[id] !== undefined);
  const drawn = [...new Set(known)].sort((a, b) => rank(a) - rank(b));
  const out: AccessoryLayers = { back: '', skin: '', front: '', edge: '' };
  for (const id of drawn) {
    const a = ACCESSORY_ART[id];
    if (!a) continue;
    const dy = TOP[a.anchor];
    if (a.back) out.back += placed(a.back, LEFT, dy, SCALE);
    if (a.skin) out.skin += placed(a.skin, LEFT, dy, SCALE);
    out.front += placed(a.art, LEFT, dy, SCALE);
    if (edge > 0) out.edge += placed(contourOf(id, a.art, edge), LEFT, dy, SCALE);
  }
  return out;
}

// The canvas's standing capsule (a collection tile, Aksesuarlarım: viewBox 0 -12 100 140) wearing
// the accessory; `silhouette` draws all of it in one colour (an accessory not owned yet), without
// its halo and its motions.
const FIGURE_V1 =
  '<rect x="24" y="22" width="52" height="92" rx="26" fill="#F5E6CC"/>' +
  '<path d="M60 24A26 26 0 0 1 76 48V88A26 26 0 0 1 60 112Z" fill="#D9CBB4"/>' +
  '<rect x="28" y="41" width="45" height="22" rx="11" fill="#E2F0D9"/>' +
  '<circle cx="39" cy="52" r="4.6" fill="#1B1530"/><circle cx="61" cy="52" r="4.6" fill="#1B1530"/>' +
  '<path d="M42 70q8 6 16 0" fill="none" stroke="#1B1530" stroke-width="4" stroke-linecap="round"/>';
const BODY_V2 =
  '<rect x="24" y="22" width="52" height="104" rx="26" fill="#F5E6CC"/>' +
  '<clipPath id="fig-b"><rect x="24" y="22" width="52" height="104" rx="26"/></clipPath>' +
  '<rect x="61" y="0" width="30" height="140" fill="#D9CBB4" clip-path="url(#fig-b)"/>';
const VISOR_V2 = '<rect x="31.43" y="35" width="37.14" height="20.43" rx="10.21" fill="#E2F0D9"/>';
const EYES_V2 =
  '<circle cx="42.57" cy="45.21" r="3.9" fill="#1B1530"/><circle cx="57.43" cy="45.21" r="3.9" fill="#1B1530"/>';
const MOUTH_V2 =
  '<path d="M43.33 60.57q6.31 5.2 12.63 0" fill="none" stroke="#1B1530" stroke-width="2.8" stroke-linecap="round"/>';

function figureOf(id: string, a: AccessoryArt | undefined, halo: boolean): string {
  if (!a) return FIGURE_V1;
  if (a.anchor !== 'body') return FIGURE_V1 + a.art;
  const slots = slotsOf(id);
  return (
    (halo ? (a.back ?? '') : '') +
    BODY_V2 +
    (a.skin ?? '') +
    VISOR_V2 +
    (slots.includes('e') ? '' : EYES_V2) +
    (NO_MOUTH.has(id) ? '' : MOUTH_V2) +
    a.art
  );
}

export function accessoryFigure(id: string, silhouette: string | null = null): string {
  const a = ACCESSORY_ART[id];
  const inner = figureOf(id, a, silhouette === null);
  const drawn = silhouette
    ? inner
        .replace(/ data-fx="[^"]*" data-o="[^"]*" data-k="[^"]*"/g, '')
        .replace(/fill="(?:#[0-9A-Fa-f]{3,8}|url\([^)]*\))"/g, `fill="${silhouette}"`)
        .replace(/stroke="(?:#[0-9A-Fa-f]{3,8}|url\([^)]*\))"/g, `stroke="${silhouette}"`)
        .replace(/ (?:fill-)?opacity="[^"]*"/g, '')
    : inner;
  return `<svg viewBox="0 -12 100 140" width="100%" height="100%" aria-hidden="true">${drawn}</svg>`;
}

function withoutGroup(svg: string, mark: RegExp): string {
  let out = svg;
  for (;;) {
    const at = out.search(mark);
    if (at < 0) return out;
    let depth = 0;
    const tag = /<\/?g\b[^>]*>/g;
    tag.lastIndex = at;
    let end = out.length;
    for (let m = tag.exec(out); m; m = tag.exec(out)) {
      depth += m[0].startsWith('</') ? -1 : m[0].endsWith('/>') ? 0 : 1;
      if (depth === 0) {
        end = m.index + m[0].length;
        break;
      }
    }
    out = out.slice(0, at) + out.slice(end);
  }
}

// A white copy of a drawing, every shape `edge` thicker on each side, still and without its shine:
// laid under the drawing it is its outline (a sticker's white edge, a card's thin contour).
export function edgeOf(art: string, edge: number, ink = '#FFFFFF', tag = 'edge'): string {
  const white = withoutGroup(art, /<g data-fx="glint"/)
    .replace(/ data-fx="[^"]*" data-o="[^"]*" data-k="[^"]*"/g, '')
    .replace(/ id="([^"]*)"/g, ` id="$1-${tag}"`)
    .replace(/url\(#([^)]*)\)/g, `url(#$1-${tag})`)
    .replace(/ (?:fill-)?opacity="[^"]*"/g, '')
    .replace(/fill="(?:#[0-9A-Fa-f]{3,8}|url\([^)]*\))"/g, `fill="${ink}"`)
    .replace(/stroke="(?:#[0-9A-Fa-f]{3,8}|url\([^)]*\))"/g, `stroke="${ink}"`)
    .replace(
      /stroke-width="([\d.]+)"/g,
      (_m, sw: string) => `stroke-width="${num(Number(sw) + edge * 2)}"`,
    )
    .replace(
      /<(path|circle|rect|ellipse)\b(?![^>]*\bstroke=)/g,
      `<$1 stroke="${ink}" stroke-width="${num(edge * 2)}"`,
    );
  return `<g stroke-linejoin="round" stroke-linecap="round">${white}</g>`;
}

// A contour only outside the drawing: its white copy masked by the drawing itself (black, the same
// size), so a see-through part (Kuzey ışığı's ribbons) does not show white through it.
function contourOf(id: string, art: string, edge: number): string {
  const mask = `${id}-contour`;
  return (
    `<mask id="${mask}" maskUnits="userSpaceOnUse" x="-80" y="-80" width="260" height="300">` +
    `<rect x="-80" y="-80" width="260" height="300" fill="#FFFFFF"/>` +
    `${edgeOf(art, 0, '#000000', 'cut')}</mask>` +
    `<g mask="url(#${mask})">${edgeOf(art, edge)}</g>`
  );
}
